// A list at scale: which instances a page of a list shows. The address holds all of it, so a page of
// a list is a link anyone can follow: `_page` (the page, from 1), `_status` (a lifecycle state) and
// `_q` (text), beside the `query` (and its arguments) the view of the domain's own queries uses. The
// names start with an underscore so they never collide with a query's own argument. The server
// narrows and cuts the rows; the browser only orders the page it was given.
import { at } from "../names.ts";
import type { Aggregate } from "../schema.ts";
import { summaryText } from "./outline.ts";
import { href } from "./html.ts";

type State = Record<string, unknown>;
type Row = [string, State];

/** The attribute names that name an instance to a person, in the order they are tried. */
const TITLES = ["title", "name", "label"];

/** What a list is showing: the filters in force, which page, and how many there are. */
export interface View {
  q: string;
  status: string;
  page: number;
  pages: number;
  size: number;
  /** How many rows match the filters. */
  total: number;
  /** How many rows there are before any filter. */
  unfiltered: number;
  /** The first and last row shown, counted from 1; both 0 when none. */
  from: number;
  to: number;
  /** The other pairs of the address (the view's query and its arguments), kept on every link. */
  params: [string, string][];
}

/** The states a lifecycle can be in, the one it starts in first. */
export function statesOf(agg: Aggregate): string[] {
  const lifecycle = agg.lifecycle;
  if (!lifecycle) return [];
  return [...new Set([lifecycle.default, ...lifecycle.transitions.flatMap((move) => [...move.from, move.to])])];
}

/** The attribute that names an instance to a person: its title, name or label, when it has a plain one. */
export function titleOf(agg: Aggregate): string | undefined {
  const plain = agg.attributes.filter((attr) => !attr.list && attr.widget !== "body").map((attr) => attr.name);
  return TITLES.find((name) => plain.includes(name));
}

/** The text a search looks in: the identity, and the title. */
function searchable(agg: Aggregate, [id, state]: Row): string {
  const title = titleOf(agg);
  return [id, title ? summaryText(state[title]) : ""].join(" ").toLowerCase();
}

/** `status` when it is a state the lifecycle has, else none. */
export const knownStatus = (agg: Aggregate, status: string): string => (statesOf(agg).includes(status) ? status : "");

/** The rows that are in `status` (when it is a state the lifecycle has) and hold every word of `q`. */
export function narrow(agg: Aggregate, rows: Row[], q: string, status: string): Row[] {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  const inState = status !== "" && agg.lifecycle ? (row: Row) => String(row[1][agg.lifecycle?.field ?? ""]) === status : () => true;
  return rows.filter((row) => inState(row) && words.every((word) => searchable(agg, row).includes(word)));
}

/** The address of a list with its filters; `extra` overrides pairs, and an empty value leaves one out. */
export function listHref(agg: Aggregate, params: [string, string][], extra: Record<string, string> = {}): string {
  const pairs = [...params.filter(([key]) => !(key in extra)), ...Object.entries(extra)].filter(([, value]) => value !== "");
  const query = new URLSearchParams(pairs).toString();
  return `${href(...at(agg))}${query ? `?${query}` : ""}`;
}

/** What a page of `matching` rows shows: the filters, the page asked for (clamped to the pages there are) and the counts. */
export function viewOf(matching: number, unfiltered: number, asked: { q: string; status: string; page: number; size: number; params: [string, string][] }): View {
  const pages = Math.max(1, Math.ceil(matching / asked.size));
  const page = Math.min(Math.max(1, asked.page), pages);
  const from = matching === 0 ? 0 : (page - 1) * asked.size + 1;
  return { q: asked.q, status: asked.status, page, pages, size: asked.size, total: matching, unfiltered, from, to: Math.min(matching, page * asked.size), params: asked.params };
}

/** The rows of the page `view` names. */
export const slice = (rows: Row[], view: View): Row[] => rows.slice(Math.max(0, view.from - 1), view.to);
